use actix_web::{web, App, HttpServer, HttpResponse, middleware};
use deadpool_postgres::{Config, Pool, Runtime};
use tokio_postgres::NoTls;
use serde::Deserialize;
use std::sync::atomic::{AtomicU64, Ordering};

static TRANSFER_COUNTER: AtomicU64 = AtomicU64::new(0);

#[derive(Deserialize)]
struct TransferRequest {
    from_account: i64,
    to_account: i64,
    amount: f64,
}

#[derive(Deserialize)]
struct BalanceQuery {
    account_id: i64,
}

async fn check_balance(pool: &Pool, account_id: i64) -> Result<f64, Box<dyn std::error::Error>> {
    let client = pool.get().await?;
    let row = client
        .query_one(
            "SELECT balance FROM accounts WHERE id = $1",
            &[&account_id],
        )
        .await?;
    Ok(row.get::<_, f64>(0))
}

async fn update_balance(pool: &Pool, account_id: i64, new_balance: f64) -> Result<(), Box<dyn std::error::Error>> {
    let client = pool.get().await?;
    client
        .execute(
            "UPDATE accounts SET balance = $1 WHERE id = $2",
            &[&new_balance, &account_id],
        )
        .await?;
    Ok(())
}

async fn transfer(
    pool: web::Data<Pool>,
    req: web::Json<TransferRequest>,
) -> HttpResponse {
    let transfer_id = TRANSFER_COUNTER.fetch_add(1, Ordering::SeqCst);

    // Step 1: Check sender balance
    let sender_balance = match check_balance(pool.get_ref(), req.from_account).await {
        Ok(b) => b,
        Err(e) => return HttpResponse::InternalServerError().body(format!("DB error: {}", e)),
    };

    // Step 2: Validate sufficient funds
    if sender_balance < req.amount {
        return HttpResponse::BadRequest().body("Insufficient funds");
    }

    // Step 3: Debit sender (TOCTOU window between check and update)
    let new_sender_balance = sender_balance - req.amount;
    if let Err(e) = update_balance(pool.get_ref(), req.from_account, new_sender_balance).await {
        return HttpResponse::InternalServerError().body(format!("Debit failed: {}", e));
    }

    // Step 4: Credit receiver
    let receiver_balance = match check_balance(pool.get_ref(), req.to_account).await {
        Ok(b) => b,
        Err(e) => {
            // Attempt rollback
            let _ = update_balance(pool.get_ref(), req.from_account, sender_balance).await;
            return HttpResponse::InternalServerError().body(format!("Credit check failed: {}", e));
        }
    };

    let new_receiver_balance = receiver_balance + req.amount;
    if let Err(e) = update_balance(pool.get_ref(), req.to_account, new_receiver_balance).await {
        let _ = update_balance(pool.get_ref(), req.from_account, sender_balance).await;
        return HttpResponse::InternalServerError().body(format!("Credit failed: {}", e));
    }

    HttpResponse::Ok().json(serde_json::json!({
        "transfer_id": transfer_id,
        "from": req.from_account,
        "to": req.to_account,
        "amount": req.amount,
        "new_sender_balance": new_sender_balance
    }))
}

async fn get_balance(
    pool: web::Data<Pool>,
    query: web::Query<BalanceQuery>,
) -> HttpResponse {
    match check_balance(pool.get_ref(), query.account_id).await {
        Ok(balance) => HttpResponse::Ok().json(serde_json::json!({"balance": balance})),
        Err(e) => HttpResponse::InternalServerError().body(format!("Error: {}", e)),
    }
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    let mut cfg = Config::new();
    cfg.host = Some(std::env::var("DB_HOST").unwrap_or_else(|_| "localhost".into()));
    cfg.dbname = Some("payments".into());
    cfg.user = Some("app_user".into());
    cfg.password = Some(std::env::var("DB_PASSWORD").unwrap_or_else(|_| "secret".into()));
    cfg.port = Some(6432); // pgBouncer port

    let pool = cfg.create_pool(Some(Runtime::Tokio1), NoTls).unwrap();

    HttpServer::new(move || {
        App::new()
            .app_data(web::Data::new(pool.clone()))
            .wrap(middleware::Logger::default())
            .route("/transfer", web::post().to(transfer))
            .route("/balance", web::get().to(get_balance))
    })
    .workers(8)
    .bind("0.0.0.0:8080")?
    .run()
    .await
}
